// Create the LocalStorageWrapper interface here
interface LocalStorageWrapper {
  getItem<T>(key: string): T | null;
  setItem<T>(key: string, value: T): void;
  removeItem(key: string): void;
  clear(): void;
}

// Implement getItem method here
const localStorageWrapper: LocalStorageWrapper = {
  getItem<T>(key: string): T | null {
    try {
      const item = localStorage.getItem(key);
      if (item === null) return null;
      return JSON.parse(item) as T;
    } catch {
      console.error('Error reading from localStorage');
      return null;
    }
  },
  setItem<T>(key: string, value: T): void {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      console.error('Error writing to localStorage');
    }
  },
  removeItem(key: string): void {
    localStorage.removeItem(key);
  },
  clear(): void {
    localStorage.clear();
  }
};

// Create the TypedLocalStorage class here
class TypedLocalStorage implements LocalStorageWrapper {
  getItem<T>(key: string): T | null {
    return localStorageWrapper.getItem<T>(key);
  }
  setItem<T>(key: string, value: T): void {
    localStorageWrapper.setItem(key, value);
  }
  removeItem(key: string): void {
    localStorageWrapper.removeItem(key);
  }
  clear(): void {
    localStorageWrapper.clear();
  }
}

// Initialize the typedStorage instance here
const typedStorage = new TypedLocalStorage();

